details.patch:
--- public/style.css
+++ public/style.css
@@ -8,9 +8,9 @@
 button { padding: 10px 16px; border: 1px solid #2456a0; border-radius: 6px; background: #2456a0; color: white; font: inherit; cursor: pointer; }
 button:hover { background: #1a407a; }
 button:disabled { opacity: .6; cursor: wait; }
 :focus-visible { outline: 3px solid #d58a00; outline-offset: 3px; }
-.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; border-top: 1px solid #dce3eb; padding: 16px 0; }
+.project-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; border-top: 1px solid #dce3eb; padding: 16px 0; }
 .project-row span { overflow-wrap: anywhere; min-width: 0; }
 .project-row button { flex-shrink: 0; }
 [role="alert"] { color: #a32020; }
 select { margin: 16px 0 16px 12px; padding: 8px; font: inherit; }
